def add_tag(tag, tags=[]):        # trap: one list shared by all calls
    tags.append(tag)
    return tags

print(add_tag("a"))   # ['a']
print(add_tag("b"))   # ['a', 'b']

def add_tag_safe(tag, tags=None):
    if tags is None:
        tags = []                 # a fresh list on every call
    tags.append(tag)
    return tags

def total(*nums):
    return sum(nums)

print(total(1, 2, 3))   # 6

